#!/usr/bin/python
from __future__ import print_function

import csv
import os
import sys
import tempfile

base = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
output_path = os.path.join(base, 'merged.csv')


def fail(message):
    raise ValueError(message)


def main(paths):
    if not paths:
        fail('usage: merge CSV_FILE [CSV_FILE ...]')

    header = None
    records = {}

    for path in paths:
        try:
            stream = open(path, 'rb')
        except IOError as exc:
            fail("cannot open %s: %s" % (path, exc))

        try:
            reader = csv.reader(stream)
            try:
                file_header = next(reader)
            except StopIteration:
                fail('%s: empty CSV file' % path)

            if file_header and file_header[0].startswith('\xef\xbb\xbf'):
                file_header[0] = file_header[0][3:]
            if not file_header or file_header[0] != 'transaction_id':
                fail('%s: first column must be transaction_id' % path)
            if header is None:
                header = file_header
            elif file_header != header:
                fail('%s: header does not match the other exports' % path)

            for line_number, row in enumerate(reader, 2):
                if not row or (len(row) == 1 and row[0] == ''):
                    continue
                if len(row) != len(header):
                    fail('%s:%d: expected %d fields, found %d' %
                         (path, line_number, len(header), len(row)))
                try:
                    transaction_id = int(row[0], 10)
                except ValueError:
                    fail("%s:%d: transaction_id %r is not an integer" %
                         (path, line_number, row[0]))

                previous = records.get(transaction_id)
                if previous is None:
                    records[transaction_id] = (row, path, line_number)
                elif previous[0][1:] != row[1:]:
                    fail("conflicting duplicate transaction_id %s: "
                         "%s:%d has %r, but %s:%d has %r" %
                         (transaction_id, previous[1], previous[2],
                          previous[0][1:], path, line_number, row[1:]))
        except csv.Error as exc:
            fail('%s: invalid CSV: %s' % (path, exc))
        finally:
            stream.close()

    temporary = tempfile.NamedTemporaryFile(
        prefix='.merged.csv.', dir=base, delete=False)
    temporary_path = temporary.name
    try:
        writer = csv.writer(temporary, lineterminator='\n')
        writer.writerow(header)
        for transaction_id in sorted(records):
            writer.writerow(records[transaction_id][0])
        temporary.flush()
        os.fsync(temporary.fileno())
        temporary.close()
        os.chmod(temporary_path, 0o644)
        os.rename(temporary_path, output_path)
    except:
        try:
            temporary.close()
        finally:
            if os.path.exists(temporary_path):
                os.unlink(temporary_path)
        raise


if __name__ == '__main__':
    try:
        main(sys.argv[1:])
    except Exception as exc:
        print('merge: %s' % exc, file=sys.stderr)
        sys.exit(1)
